    "title": "当代海派水墨艺术首次整体亮相新加坡",
    "link": "https://m.thepaper.cn/newsDetail_forward_34535575",
    "pub_date": "2026-11-22 21:13:49",
    "author": "",
    "description": "澎湃新闻获悉，汇聚40余位上海知名艺术家80多幅作品的“新海派水墨・陶艺艺术特展\"日前在新加坡中国文化中心正式对外展出，这也是迄今在新加坡举办的规模最大的新海派艺术展，基本呈现了当下新海派水墨艺术整体的创作态势。 展览由上海市中国陶瓷艺术家协会、上海夜航船文化艺术基金会联合主办，上海市收藏协会、上海陈佩秋公益基金会协办，得到新加坡中国文化中心、上海市对外文化交流协会支持。 “这次展览将九大创作群体、四代创作梯队同时带到新加坡，让海外观众…",
    "content": "澎湃新闻获悉，汇聚40余位上海知名艺术家80多幅作品的“新海派水墨・陶艺艺术特展\"日前在新加坡中国文化中心正式对外展出，这也是迄今在新加坡举办的规模最大的新海派艺术展，基本呈现了当下新海派水墨艺术整体的创作态势。 展览由上海市中国陶瓷艺术家协会、上海夜航船文化艺术基金会联合主办，上海市收藏协会、上海陈佩秋公益基金会协办，得到新加坡中国文化中心、上海市对外文化交流协会支持。 “这次展览将九大创作群体、四代创作梯队同时带到新加坡，让海外观众看到的不是一个或几个艺术家的面貌，而是新海派整体的创作生态。这种整体性的呈现，既…"
