    "pub_date": "2026-11-22 20:17:09",
    "author": "",
    "description": "新华社北京11月22日电 韩国近期频发利用人工智能(AI)工具考试作弊事件，多所学校发布应对措施。据韩国媒体22日报道，首尔一所大学强制要求考生在考试中穿着一次性围裙，以防他们在身上藏匿微型摄像头等设备用于作弊。 据韩国SBS电视台等媒体报道，位于首尔的庆熙大学在21日和22日举行的考试中，为考生准备约3万件一次性白色无纺布围裙，作为防AI作弊措施之一。校方规定，考生在考试期间必须穿上围裙，不配合者不得参与考试。此外，考生不得携带任何电…",
    "content": "新华社北京11月22日电 韩国近期频发利用人工智能(AI)工具考试作弊事件，多所学校发布应对措施。据韩国媒体22日报道，首尔一所大学强制要求考生在考试中穿着一次性围裙，以防他们在身上藏匿微型摄像头等设备用于作弊。 据韩国SBS电视台等媒体报道，位于首尔的庆熙大学在21日和22日举行的考试中，为考生准备约3万件一次性白色无纺布围裙，作为防AI作弊措施之一。校方规定，考生在考试期间必须穿上围裙，不配合者不得参与考试。此外，考生不得携带任何电子设备及耳塞，长发考生必须露出耳朵。按韩国媒体说法，此举是为防止考生通过微型耳机…"
