    "content": "中国三大证券交易所宣布，将股票融资保证金比例下限从100%降至80%，以提振市场流动性。监管人士估计，新措施理论上可为股市释放近4000亿元（人民币，下同，772亿新元）的增量资金。 综合澎湃新闻、新华社等报道，经中国证监会批准，上海、深圳和北京证券交易所星期天（11月22日）宣布上述调整，新规定将于11月30日起实施。 融资保证金比例决定投资者借钱买入股票的杠杆倍数。调整后，投资者以100万元保证金，可向券商融资买入最多125万元证券，高于此前的100万元，相当于融资杠杆倍数从一倍提高至1.25倍。 据澎湃新闻报…"
