    "description": "台湾九合一选举进入最后冲刺阶段，亲民党主席宋楚瑜公开表态支持民进党籍基隆市长候选人童子玮。童子玮对此表达感谢，强调地方治理应超越政党立场，共同目标是让基隆变得更好。 综合台湾《联合报》和中央广播电台报道，宋楚瑜星期六（11月21日）前往基隆，为亲民党提名的市议员候选人郑素祯站台助选时，公开表态支持童子玮，并拉起在场童子玮秘书郭亭琪的手，高喊“加油”。 宋楚瑜回忆，2000年他参选总统时，童子玮的祖父、基隆庆安宫前主委童永，曾无条件提供场…",
