    "content": "新华社北京11月22日电 近日，在中央反腐败协调小组国际追逃追赃工作办公室统筹协调下，经与有关国家反腐败机构密切合作，外逃行贿犯罪嫌疑人刘贤志在境外落网并被遣返回国。 刘贤志，男，1977年2月生，北京志骏腾达建筑工程有限公司实际控制人，涉嫌向多名公职人员行贿，于2026年5月外逃。陕西省监察机关依法对刘立案调查，扎实开展追逃追赃工作，积极开展国际执法合作，于近日将其缉拿归案。 中央追逃办负责人表示，刘贤志归案是纪检监察机关贯彻党的二十届五中全会精神，落实反跨境腐败法，深入开展追逃追赃工作的最新成果。我们将持续深化…"
