    "content": "经历前期快速扩张后，惠民保市场正进入存量调整阶段。 11月21日，复旦大学经济学院副院长、风险管理与保险学系主任许闲教授团队发布的《2026年城市定制型商业医疗保险（惠民保）知识图谱》（下称《报告》）显示，截至2026年8月31日，全国累计推出325款惠民保产品，其中196款正常运行，129款已停售。今年前8个月，全国仅新增6款惠民保产品。 《报告》显示，2026年1月1日至8月31日，全国新增的6款惠民保产品分布在河北、江西、新疆、甘肃和辽宁等地。产品增量进一步收窄，新增供给更多体现为局部补充、统筹调整和产品形态…"
