    "content": "新华社渥太华11月22日电（记者林威）在加拿大传统美食中，枫糖牢牢占据一席之地。这抹甜蜜的味道既是不少加拿大人抵御长冬严寒的灵魂慰藉，也是太空深处加拿大宇航员抚慰乡愁的贴心零食。原住民的智慧孕育了这一美食文化象征，而加拿大在全球枫糖产业的竞争优势为其应对与美国的贸易冲突添加了底气。 原住民的智慧 加拿大人对枫糖有各种“花式”吃法，比如冰枫糖。将琥珀色的枫糖浆加热后直接浇在干净、纯白的新雪上。糖浆遇冷迅速变得黏稠、有弹性。人们用一根冰棒棍顺势一卷，就做成了一支带有冰雪清凉与浓郁焦糖香的冰枫糖。这是加拿大漫漫寒冬最经典…"
