    "description": "三安光电公告称，公司董事会于2026年11月21日收到副董事长兼总经理林科闯的书面辞职申请，其因个人身体原因，申请辞去公司第十一届董事会副董事长、董事、下属委员会委员、总经理及下属子公司相关职务，辞职后不再担任公司任何职务，辞职申请自送达董事会之日起生效。本次辞职不会导致公司董事会成员低于法定最低人数，不影响董事会正常运作。在聘任新任总经理前，暂由公司董事长林志强代行总经理职责。",
