    "content": "新华社东京11月22日电（记者梁晨 李子越）据日本媒体22日报道，日本文部科学大臣关芳弘因邀请政府部门工作人员出席政治筹款活动等问题持续受到质疑，朝野人士要求其辞职。 日本《读卖新闻》当天报道说，要求关芳弘辞职的声音已在执政党内扩大，首相高市早苗将根据在野党的动向和舆论反应，最终决定其去留。 日本共同社报道说，在野党国民民主党党首玉木雄一郎表示，关芳弘的行为足以成为向参议院提交问责决议案的理由，并敦促他自行决定去留。 据日本媒体报道，关芳弘此前举办政治筹款活动，向参会的生物医药企业人士每人收取9万日元（约合人民币3…"
