    "content": "中国四川稻城亚丁景区因冬春季冰冻天气带来安全隐患，以及生态修复需要，将从星期四（11月26日）起封闭金刚挑战线，直至明年4月15日。 稻城亚丁景区管理局上星期五（11月20日）发布公告称，因冬春冰冻期安全隐患大及生态修复需要，稻城亚丁景区内长线（金刚挑战线）游览区域实施封闭管理。 公告提到，从今年11月26日至明年4月15日，稻城亚丁景区内长线（金刚挑战线）贡嘎措至牛奶海、五色海区域将进行封闭管理。 公告称，封闭管理期间，因游客及社会其他人员私自进入封闭管理区域造成的人身安全后果自负，同时景区将按相关规定依法依规处…"
